#include "tigersheets/main_window.hpp"
#include "tigersheets/grid.hpp"
#include <QApplication>
#include <QContextMenuEvent>
#include <QInputDialog>
#include <QMenu>
#include <QMessageBox>
#include <QPushButton>
#include <QTabBar>
#include <QTableView>
#include <QTemporaryDir>
#include <QTimer>
#include <QtTest/QTest>
#include <iostream>
#include <stdexcept>
using namespace tigersheets;
namespace {
void require(bool okay,const std::string& message){if(!okay)throw std::runtime_error(message);}
struct Fixture {
 MainWindow window;QTabBar* tabs;WorksheetModel* model;QString first,second,third;
 Fixture(){window.resize(1400,850);window.show();QApplication::processEvents();tabs=window.findChild<QTabBar*>("workspace.sheets");auto* grid=window.findChild<QTableView*>("worksheet.grid");model=dynamic_cast<WorksheetModel*>(grid->model());require(tabs&&model,"worksheet tabs and model exist");first=model->sheetId();require(window.executeCommand("sheet.add"),"add Sheet2");second=model->sheetId();require(window.executeCommand("sheet.add"),"add Sheet3");third=model->sheetId();tabs->setCurrentIndex(0);QApplication::processEvents();}
 QMenu* openMenu(int tab){const auto point=tabs->tabRect(tab).center();QContextMenuEvent event(QContextMenuEvent::Mouse,point,tabs->mapToGlobal(point));QApplication::sendEvent(tabs,&event);QApplication::processEvents();auto* menu=qobject_cast<QMenu*>(QApplication::activePopupWidget());require(menu&&menu->isVisible(),"right-clicking a worksheet tab exposes a native menu");return menu;}
 QAction* action(QMenu* menu,const QString& name){for(auto* item:menu->actions())if(item->text().remove('&').remove(QChar(0x2026)).trimmed()==name)return item;throw std::runtime_error("worksheet tab menu contains "+name.toStdString());}
 void click(QMenu* menu,QAction* item){QTest::mouseClick(menu,Qt::LeftButton,Qt::NoModifier,menu->actionGeometry(item).center());QApplication::processEvents();}
};
void renameFromTab(){
 Fixture f;require(f.model->apply(Json::array({{{"type","set_cell"},{"sheet",f.first.toStdString()},{"row",1},{"col",1},{"input","=Sheet2!B3"}},{{"type","set_cell"},{"sheet",f.second.toStdString()},{"row",3},{"col",2},{"input","42"}}})),"seed cross-sheet reference and target data");const auto before=f.window.currentSession().snapshot();auto* menu=f.openMenu(1);auto* rename=f.action(menu,"Rename");require(rename->isEnabled(),"Rename is available for the clicked tab");bool opened=false;std::string failure;
 QTimer::singleShot(0,[&]{auto* dialog=qobject_cast<QInputDialog*>(QApplication::activeModalWidget());if(!dialog){failure="Rename opens a native sheet-name dialog";return;}opened=true;if(dialog->textValue()!="Sheet2")failure="Rename starts with the right-clicked worksheet name";dialog->setTextValue("Budget 2026");dialog->accept();});f.click(menu,rename);require(failure.empty(),failure);require(opened,"Rename dialog opens from worksheet tab");const auto& book=f.window.currentSession().snapshotView();require(book.at("sheets")[1].at("name")=="Budget 2026"&&f.tabs->tabText(1)=="Budget 2026","rename updates the clicked tab and workbook");require(f.model->sheetId()==f.second&&f.tabs->currentIndex()==1,"renaming an inactive tab targets and selects that worksheet");require(book.at("sheets")[0].at("cells")[0].at("input")=="='Budget 2026'!B3","renaming updates existing cross-sheet references");require(f.window.executeCommand("undo"),"renaming can be undone");const auto restored=f.window.currentSession().snapshot();require(restored.at("sheets")==before.at("sheets"),"one Undo restores both worksheet name and dependent formula");require(f.tabs->tabText(1)=="Sheet2","Undo refreshes worksheet tabs");
}
void deleteFromTab(){
 Fixture f;require(f.model->apply(Json::array({{{"type","set_cell"},{"sheet",f.second.toStdString()},{"row",3},{"col",2},{"input","42"},{"style",{{"bold",true},{"numberFormat","$#,##0.00"}}}},{{"type","set_cell"},{"sheet",f.third.toStdString()},{"row",1},{"col",1},{"input","Next worksheet"}}})),"seed deleted-sheet content and next sheet");const auto before=f.window.currentSession().snapshot();auto* menu=f.openMenu(1);auto* remove=f.action(menu,"Delete");require(remove->isEnabled(),"Delete is available when another worksheet remains");bool opened=false;std::string failure;
 QTimer::singleShot(0,[&]{auto* dialog=qobject_cast<QMessageBox*>(QApplication::activeModalWidget());if(!dialog){failure="Delete asks for native confirmation";return;}opened=true;if(!dialog->text().contains("Sheet2"))failure="Delete confirmation identifies the clicked worksheet";if(dialog->defaultButton()!=dialog->button(QMessageBox::Cancel))failure="Delete defaults to Cancel";QTest::mouseClick(dialog->button(QMessageBox::Cancel),Qt::LeftButton);});f.click(menu,remove);require(failure.empty(),failure);require(opened,"Delete confirmation opens");require(f.window.currentSession().snapshot()==before,"Cancel leaves all sheets, data, formatting and history unchanged");require(f.tabs->count()==3&&f.model->sheetId()==f.second,"Cancel keeps the clicked worksheet available");
 menu=f.openMenu(1);remove=f.action(menu,"Delete");QTimer::singleShot(0,[&]{auto* dialog=qobject_cast<QMessageBox*>(QApplication::activeModalWidget());if(!dialog){failure="Delete confirmation opens again";return;}QTest::mouseClick(dialog->button(QMessageBox::Yes),Qt::LeftButton);});f.click(menu,remove);require(failure.empty(),failure);const auto& after=f.window.currentSession().snapshotView();require(after.at("sheets").size()==2&&f.tabs->count()==2,"confirmed Delete removes exactly one worksheet and tab");require(after.at("sheets")[0].at("id")==f.first.toStdString()&&after.at("sheets")[1].at("id")==f.third.toStdString(),"Delete targets the right-clicked worksheet");require(f.model->sheetId()==f.third&&f.tabs->currentIndex()==1&&f.tabs->tabData(1).toString()==f.third,"deleting selects the next worksheet with tabs and model in agreement");require(f.model->raw(0,0)=="Next worksheet","worksheet grid shows the selected surviving sheet");require(f.window.executeCommand("undo"),"Delete is undoable");require(f.window.currentSession().snapshotView().at("sheets")==before.at("sheets"),"one Undo restores worksheet order, data and formatting");require(f.tabs->count()==3&&f.tabs->tabData(f.tabs->currentIndex()).toString()==f.model->sheetId(),"Undo keeps worksheet tab selection consistent");require(f.window.executeCommand("redo")&&f.tabs->count()==2,"Redo removes the worksheet again");
}
void lastWorksheetIsProtected(){
 Fixture f;require(f.model->apply(Json::array({{{"type","delete_sheet"},{"sheet",f.third.toStdString()}},{{"type","delete_sheet"},{"sheet",f.second.toStdString()}}})),"leave one worksheet");const auto before=f.window.currentSession().snapshot();auto* menu=f.openMenu(0);require(!f.action(menu,"Delete")->isEnabled(),"the last worksheet's Delete menu entry is disabled");menu->close();require(!f.window.executeCommand("sheet.delete"),"direct Delete also protects the last worksheet");require(f.window.lastError().contains("last worksheet"),"last-sheet restriction explains why Delete is unavailable");require(f.window.currentSession().snapshot()==before,"last-sheet restriction preserves workbook and history");
}
void renameCancelAndInvalidName(){
 Fixture f;const auto before=f.window.currentSession().snapshot();auto* menu=f.openMenu(1);std::string failure;QTimer::singleShot(0,[&]{auto* dialog=qobject_cast<QInputDialog*>(QApplication::activeModalWidget());if(!dialog){failure="Rename opens its native dialog";return;}dialog->setTextValue("Cancelled rename");dialog->reject();});f.click(menu,f.action(menu,"Rename"));require(failure.empty(),failure);require(f.window.currentSession().snapshot()==before&&f.tabs->tabText(1)=="Sheet2","cancelled Rename preserves worksheet name and undo history");
 QTimer::singleShot(0,[&]{auto* dialog=qobject_cast<QInputDialog*>(QApplication::activeModalWidget());if(!dialog){failure="Rename opens for invalid-name check";return;}dialog->setTextValue("Sheet1");dialog->accept();});require(!f.window.executeCommand("sheet.rename"),"duplicate worksheet names are refused");require(failure.empty(),failure);require(f.window.currentSession().snapshot()==before,"invalid Rename is atomic");require(!f.window.lastError().isEmpty(),"invalid Rename reports the reason instead of silently failing");
}
void doubleClickOnlyRenamesAnActualTab(){
 Fixture f;f.tabs->setMinimumWidth(600);QApplication::processEvents();const auto before=f.window.currentSession().snapshot();const auto blank=QPoint(f.tabs->tabRect(f.tabs->count()-1).right()+30,f.tabs->height()/2);require(f.tabs->rect().contains(blank)&&f.tabs->tabAt(blank)==-1,"double-click fixture is inside the empty tab strip");bool opened=false;QTimer::singleShot(0,[&]{if(auto* dialog=qobject_cast<QInputDialog*>(QApplication::activeModalWidget())){opened=true;dialog->reject();}});QTest::mouseDClick(f.tabs,Qt::LeftButton,Qt::NoModifier,blank);QApplication::processEvents();require(!opened,"double-clicking the empty tab strip does not rename another worksheet");require(f.window.currentSession().snapshot()==before,"empty-strip double-click preserves workbook");
 QTimer::singleShot(0,[&]{if(auto* dialog=qobject_cast<QInputDialog*>(QApplication::activeModalWidget())){opened=true;dialog->setTextValue("Double clicked");dialog->accept();}});QTest::mouseDClick(f.tabs,Qt::LeftButton,Qt::NoModifier,f.tabs->tabRect(2).center());QApplication::processEvents();require(opened&&f.tabs->tabText(2)=="Double clicked","double-click on a worksheet tab renames that worksheet");
}
void keyboardMenuUsesCurrentTab(){
 Fixture f;f.tabs->setCurrentIndex(1);f.tabs->setFocus();QContextMenuEvent event(QContextMenuEvent::Keyboard,QPoint(-1,-1),QPoint(-1,-1));QApplication::sendEvent(f.tabs,&event);QApplication::processEvents();auto* menu=qobject_cast<QMenu*>(QApplication::activePopupWidget());require(menu&&menu->isVisible(),"keyboard context-menu request exposes current worksheet actions");require(f.action(menu,"Rename")->isEnabled()&&f.action(menu,"Delete")->isEnabled(),"keyboard context menu offers Rename and Delete");menu->close();require(f.model->sheetId()==f.second,"keyboard menu targets the current worksheet");
}
}
int main(int argc,char** argv){QApplication app(argc,argv);QTemporaryDir state;qputenv("TIGERSHEETS_STATE_DIR",state.path().toUtf8());try{const auto test=argc>1?std::string(argv[1]):std::string();if(test.empty()||test=="rename")renameFromTab();if(test.empty()||test=="delete")deleteFromTab();if(test.empty()||test=="last_sheet")lastWorksheetIsProtected();if(test.empty()||test=="rename_boundaries")renameCancelAndInvalidName();if(test.empty()||test=="double_click")doubleClickOnlyRenamesAnActualTab();if(test.empty()||test=="keyboard")keyboardMenuUsesCurrentTab();std::cout<<"worksheet sheet actions tests passed\n";}catch(const std::exception& error){std::cerr<<"FAILED: "<<error.what()<<'\n';return 1;}}
